<template>
  <section v-if="detail?.term" class="term-detail">
    <header><h2>{{ detail.term.planName }}</h2><el-tag>{{ privateState(detail.term.status) }}</el-tag></header>
    <el-alert v-if="detail.contract.contractStatus==='SUSPENDED'||detail.contract.contractStatus==='TERMINATED'" :title="`协议${privateState(detail.contract.contractStatus)}，当前不能使用密价购课；余额仍保留。`" type="warning" :closable="false" show-icon />
    <div class="term-metrics">
      <article><span>本期固定价格</span><strong>¥{{ privateMoney(detail.term.fixedPrice) }}/单</strong></article>
      <article><span>课程专户可用余额</span><strong>¥{{ privateMoney(detail.walletBalance) }}</strong></article>
      <article><span>净有效消费</span><strong>{{ detail.term.settledConsumptionAmount==null?'历史未记录':`¥${privateMoney(detail.term.settledConsumptionAmount)}` }}</strong></article>
      <article><span>距消费续期目标</span><strong>{{ detail.term.rules?.renewalPolicy==='PERFORMANCE'?`还差 ¥${privateMoney(detail.term.remainingConsumption)}`:'本期不按消费目标续期' }}</strong></article>
    </div>
    <dl><dt>资格来源</dt><dd>{{ qualificationLabel(detail.term.qualificationKind) }}</dd><dt>有效购买期</dt><dd>{{ privateDate(detail.term.startAt) }} ～ {{ detail.term.effectiveEndAt?privateDate(detail.term.effectiveEndAt):'未设置结束时间' }}</dd><dt>原订单结算截止</dt><dd>{{ privateDate(detail.term.effectiveSettlementDeadlineAt) }}</dd><dt>续期评估</dt><dd>{{ privateState(detail.term.qualificationStatus) }}<span v-if="detail.term.reviewRequired"> · 需要运营复核</span></dd><dt>已证明门槛基数</dt><dd>{{ detail.term.qualificationBasisAmount==null?'未知，不能推测历史预存':`¥${privateMoney(detail.term.qualificationBasisAmount)}` }}</dd><dt>数据核验时间</dt><dd>{{ privateDate(detail.asOf) }}</dd></dl>
    <el-alert title="结算观察期只等待本期订单完成，不延长密价购买；预存款属于可消费本金，退款回原账户。" type="info" :closable="false" show-icon />
    <article v-if="detail.nextTerm" class="next-term"><h3>已确认的下一期：{{ detail.nextTerm.planName }}</h3><p>{{ privateState(detail.nextTerm.status) }} · ¥{{ privateMoney(detail.nextTerm.fixedPrice) }}/单 · {{ privateDate(detail.nextTerm.startAt) }} ～ {{ detail.nextTerm.endAt?privateDate(detail.nextTerm.endAt):'未设置结束时间' }}</p><p v-if="detail.nextTerm.remainingUpgradeDeposit!=null">升级所需{{ detail.nextTerm.upgradeDepositPolicy==='EXISTING_BALANCE'?'存量余额':'新增资金'}} ¥{{ privateMoney(detail.nextTerm.upgradeRequiredDeposit) }}，当前还差 ¥{{ privateMoney(detail.nextTerm.remainingUpgradeDeposit) }}。</p><p>排程生效前会重新核验资格，转回资金可能影响未生效权益。</p></article>
    <h3>原周期关联订单</h3><p v-if="detail.latestSettlement">当前已结算 {{ detail.latestSettlement.orderCount??0 }} 单 · 待结算 {{ detail.latestSettlement.pendingCount??0 }} 单 · {{ privateState(detail.latestSettlement.result) }}</p><el-alert v-if="orderError" :title="orderError" type="error" :closable="false" /><el-button v-if="orderError" @click="loadOrders">重试订单明细</el-button><el-table v-loading="ordersLoading" :data="orders"><el-table-column prop="orderNo" label="原订单号" min-width="160" /><el-table-column label="原成交金额" min-width="110"><template #default="scope">¥{{ privateMoney(scope.row.orderedAmount) }}</template></el-table-column><el-table-column label="结算状态" min-width="130"><template #default="scope">{{ {PAID:'已支付待核验',QUALIFIED:'有效消费',REFUNDED:'已退款',EXCLUDED:'不计资格',PENDING:'履约待定'}[scope.row.qualificationStatus]||'待核验' }}</template></el-table-column><el-table-column label="可信完成证据" min-width="170"><template #default="scope">{{ scope.row.completedAt?'实际完成 '+privateDate(scope.row.completedAt):scope.row.completionConfirmedAt?'截止前确认 '+privateDate(scope.row.completionConfirmedAt):'未取得有效时间证据' }}</template></el-table-column></el-table><el-pagination v-if="orderTotal>20" v-model:current-page="orderPage" :page-size="20" :total="orderTotal" layout="prev,pager,next" @current-change="loadOrders" />
    <h3>周期历史</h3><div class="history-list"><article v-for="term in detail.history" :key="term.id"><div><strong>第 {{ term.termNo }} 期 · {{ term.planName }}</strong><span>{{ privateState(term.status) }} · ¥{{ privateMoney(term.fixedPrice) }}/单</span></div><small>{{ privateDate(term.startAt) }} ～ {{ term.effectiveEndAt?privateDate(term.effectiveEndAt):'未设置结束时间' }}</small><el-button link type="primary" @click="$emit('inspect',term.id)">查看本期</el-button></article></div>
    <p v-if="detail.historyMayHaveMore">当前展示最近 100 期，更多历史请联系运营核对。</p>
    <h3>权益操作记录</h3><el-empty v-if="!detail.events?.length" description="暂无本期操作记录" /><ul v-else class="event-list"><li v-for="event in detail.events" :key="event.id"><time>{{ privateDate(event.happenedAt) }}</time><span>{{ event.reason }}</span><small>{{ event.operatorName }}</small></li></ul>
  </section>
</template>
<script setup>
import {ref,watch} from 'vue';
import {getPrivateTermOrders} from '@/api/coursePrivateOperations';
import {privateDate,privateMoney,privateState,qualificationLabel} from '@/utils/coursePrivateOperations';
const props=defineProps({detail:Object,isAdmin:Boolean});defineEmits(['inspect']);
const orders=ref([]),ordersLoading=ref(false),orderError=ref(''),orderPage=ref(1),orderTotal=ref(0);let requestRevision=0;
// 周期切换的迟到响应不能覆盖当前拥有者或周期数据。
async function loadOrders(){const id=props.detail?.term?.id;if(!id)return;const revision=++requestRevision;ordersLoading.value=true;orderError.value='';orders.value=[];try{const data=(await getPrivateTermOrders(id,{page:orderPage.value,pageSize:20},props.isAdmin)).data;if(revision!==requestRevision)return;orders.value=data.records||[];orderTotal.value=data.total||0;}catch(e){if(revision===requestRevision)orderError.value=e.message||'原周期订单明细读取失败';}finally{if(revision===requestRevision)ordersLoading.value=false;}}
watch(()=>props.detail?.term?.id,()=>{orderPage.value=1;orderTotal.value=0;requestRevision++;orders.value=[];if(props.detail?.term?.id)loadOrders();},{immediate:true});
</script>
<style scoped>
.term-detail{display:grid;gap:18px}.term-detail header{display:flex;align-items:center;gap:12px;flex-wrap:wrap}h2,h3,p{margin:0}h2{font-size:21px}h3{font-size:16px}.term-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.term-metrics article,.next-term{background:var(--el-fill-color-light);padding:16px;border:1px solid var(--el-border-color-light);border-radius:10px}.term-metrics span{display:block;color:var(--el-text-color-secondary);font-size:13px}.term-metrics strong{display:block;margin-top:8px;font-size:20px}dl{display:grid;grid-template-columns:145px minmax(0,1fr);gap:10px;margin:0}dt{color:var(--el-text-color-secondary)}dd{margin:0;overflow-wrap:anywhere}.next-term p{margin-top:8px}.history-list article{padding:12px 0;border-bottom:1px solid var(--el-border-color-light);display:flex;align-items:center;gap:12px;flex-wrap:wrap}.history-list article div{display:grid;gap:4px;flex:1}.history-list span,small{color:var(--el-text-color-secondary)}.event-list{list-style:none;padding:0;margin:0;display:grid;gap:12px}.event-list li{display:grid;grid-template-columns:155px minmax(0,1fr) 80px;gap:10px}time{font-size:12px;color:var(--el-text-color-secondary)}@media(max-width:600px){.term-metrics{grid-template-columns:1fr}.term-metrics strong{font-size:18px}dl{grid-template-columns:1fr;gap:5px}dd{margin-bottom:8px}.event-list li{grid-template-columns:1fr}.history-list article small{width:100%}}
</style>
